pages.css:
.index-hero{background-color:var(--color-accent-dark);color:var(--color-accent-on-dark);}.index-hero h1{color:#ffffff;}.index-hero-inner{text-align:center;}.index-hero-lede{max-width:40rem;margin:var(--space-sm) auto var(--space-md);color:var(--color-accent-on-dark);font-size:1.1rem;}.index-hero-actions{display:flex;flex-wrap:wrap;gap:var(--space-sm);justify-content:center;}.index-hero-actions .btn-secondary{color:var(--color-accent-on-dark);border-color:var(--color-accent-on-dark);}.index-hero-actions .btn-secondary:hover{background-color:rgba(255,255,255,0.1);}

.index-price{font-size:1.75rem;font-weight:bold;color:var(--color-accent-dark);margin:0.25rem 0;}.index-price-period{font-size:1rem;font-weight:normal;color:var(--color-text-muted);}.index-feature-list{margin:0;padding-left:1.1rem;color:var(--color-text-muted);flex-grow:1;}.index-feature-list li{margin-bottom:0.3rem;}

.index-value{text-align:left;padding:var(--space-sm);}.index-value h3{color:var(--color-accent-dark);}

.index-quote{margin:0;padding:var(--space-md);background-color:var(--color-bg-alt);border-left:4px solid var(--color-accent-dark);border-radius:var(--radius);}.index-quote p{font-style:italic;margin-top:0;}.index-quote-author{margin-top:var(--space-xs);font-weight:bold;color:var(--color-text-muted);font-style:normal;}

.index-contact-grid{display:grid;grid-template-columns:1fr;gap:var(--space-md);}.index-contact-details h3{color:var(--color-accent-dark);margin-top:var(--space-sm);}.index-contact-details p{margin:0.25rem 0;}.index-hours-list{list-style:none;margin:0.5rem 0 0;padding:0;}.index-hours-list li{display:flex;justify-content:space-between;gap:var(--space-sm);padding:0.3rem 0;border-bottom:1px solid var(--color-border);}.index-hours-list li:last-child{border-bottom:none;}

@media (min-width:601px){.index-contact-grid{grid-template-columns:3fr 2fr;}}
@media (max-width:600px){.index-hero-actions{flex-direction:column;align-items:stretch;}.index-price{font-size:1.5rem;}}

